from Crypto.Util.number import bytes_to_long, getPrime
from sympy import nextprime

flag = open("flag.txt", "rb").read()
m = flag+b'\xff'*(130-len(flag))
q = getPrime(512)
p = nextprime(q)
n = p*q
e = 65537
c = pow(bytes_to_long(m),e,n)

print("n =", n)
print("e =", e)
print("c =", c)

